class TrieNode {
  kids = new Map<string, TrieNode>();
  end = false;
}

class WordDictionary {
  private root = new TrieNode();

  addWord(word: string): void {
    let node = this.root;
    for (const c of word) {
      let next = node.kids.get(c);
      if (!next) {
        next = new TrieNode();
        node.kids.set(c, next);
      }
      node = next;
    }
    node.end = true;
  }

  search(pattern: string): boolean {
    const match = (node: TrieNode, i: number): boolean => {
      if (i === pattern.length) return node.end;
      const c = pattern[i];
      if (c !== ".") {
        const next = node.kids.get(c);
        return next !== undefined && match(next, i + 1);
      }
      for (const child of node.kids.values()) if (match(child, i + 1)) return true;
      return false;
    };
    return match(this.root, 0);
  }
}

