        for c in word:
            if c not in node.kids:
                node.kids[c] = TrieNode()
            node = node.kids[c]
        node.end = True

    def search(self, pattern: str) -> bool:
        def match(node, i):
            if i == len(pattern):
                return node.end
            c = pattern[i]
            if c != ".":
                nxt = node.kids.get(c)
                return nxt is not None and match(nxt, i + 1)
            return any(match(child, i + 1) for child in node.kids.values())

        return match(self.root, 0)

